+	struct mutex		mac_cfg_lock;
 	struct clk		*pclk;
 	struct clk		*hclk;
 	struct clk		*tx_clk;
@@ -1415,6 +1417,12 @@ struct macb {
 	struct delayed_work	tx_lpi_work;
